export interface ConnectorConfig {
  /** Notion integration token with write access to the target database. */
  notionToken: string
  /** Notion database ID for the 'Signed' database. */
  notionDatabaseId: string
  /** Pipedrive stage ID that represents the Won stage. */
  pipedriveWonStageId: number
  /** Optional injected fetch for testing. */
  fetch?: typeof fetch
}

export interface PipedriveDealWebhookPayload {
  meta: {
    action: string
    entity: string
    entity_id: string
    timestamp: string
    version: string
  }
  data: {
    id: number
    title: string
    value: number
    owner: {
      name: string
      id: number
    }
    close_date: string
    stage_id: number
  }
  previous: Record<string, unknown>
}

export interface HandleResult {
  notionPageId: string
  pipedriveDealId: number
}

async function handle(
  payload: PipedriveDealWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate required fields
  if (!payload.meta) {
    throw new Error('Missing required field: meta')
  }
  if (payload.meta.action !== 'change') {
    throw new Error(`Expected meta.action === 'change', got '${payload.meta.action}'`)
  }
  if (payload.meta.entity !== 'deal') {
    throw new Error(`Expected meta.entity === 'deal', got '${payload.meta.entity}'`)
  }
  if (!payload.data) {
    throw new Error('Missing required field: data')
  }
  if (typeof payload.data.stage_id !== 'number') {
    throw new Error('Missing required field: data.stage_id')
  }
  if (payload.data.stage_id !== config.pipedriveWonStageId) {
    throw new Error(
      `Deal stage_id ${payload.data.stage_id} does not match configured Won stage ID ${config.pipedriveWonStageId}`
    )
  }
  if (!payload.data.title) {
    throw new Error('Missing required field: data.title')
  }
  if (typeof payload.data.value !== 'number') {
    throw new Error('Missing required field: data.value')
  }
  if (!payload.data.owner || !payload.data.owner.name) {
    throw new Error('Missing required field: data.owner.name')
  }
  if (!payload.data.close_date) {
    throw new Error('Missing required field: data.close_date')
  }

  // Build Notion page creation payload
  const notionPayload = {
    parent: {
      database_id: config.notionDatabaseId,
    },
    properties: {
      title: {
        title: [
          {
            type: 'text',
            text: {
              content: payload.data.title,
            },
          },
        ],
      },
      Value: {
        number: payload.data.value,
      },
      Owner: {
        select: {
          name: payload.data.owner.name,
        },
      },
      'Close Date': {
        date: {
          start: payload.data.close_date,
        },
      },
    },
  }

  const response = await fetchImpl('https://api.notion.com/v1/pages', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.notionToken}`,
      'Content-Type': 'application/json',
      'Notion-Version': '2022-06-28',
    },
    body: JSON.stringify(notionPayload),
  })

  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(
      `Notion API error: ${response.status} ${response.statusText} for POST https://api.notion.com/v1/pages - ${errorText}`
    )
  }

  const result = (await response.json()) as { id: string }
  return {
    notionPageId: result.id,
    pipedriveDealId: payload.data.id,
  }
}

export { handle }

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, PipedriveDealWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      notionToken: 'test-notion-token',
      notionDatabaseId: 'a1b2c3d4-e5f6-7890-g1h2-i3j4k5l6m7n8',
      pipedriveWonStageId: 5,
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as PipedriveDealWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.notionPageId).toBe('page-uuid')
    expect(result.pipedriveDealId).toBe(123)
  })
})

